/**
 * Jinx Butler + Organ Grinder: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Butler
 * Wiki: https://wiki.bloodontheclocktower.com/Organ_Grinder
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes.ts';
import { uncountedVote, voteHints } from '#lib/core/rules/vote-weights.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { voteWarnings } from '#lib/core/testing/votes.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Butler + Organ Grinder jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'butler', 'organgrinder');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('butler')?.name).toBe('Butler');
		expect(data.byId.get('organgrinder')?.name).toBe('Organ Grinder');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['butler', 'organgrinder'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['butler'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['organgrinder'])).not.toContain(jinx);
	});

	describe('with eyes closed, the Butler may raise their hand, counted only with their master', () => {
		const ids = ['butler', 'organgrinder', 'chef', 'empath', 'monk', 'imp'];
		const base = scenario(ids, { script: scriptOf(ids) })
			.reminder('monk', 'butler', 'Master')
			.nominate('chef', 'imp');
		const hint = (s: Scenario) =>
			voteHints(s.game, s.characters).find((h) => h.seatId === s.seat('butler'))?.onlyWith;

		it("is data in the Butler's rules", () => {
			// Wiki: "If the Organ Grinder is causing eyes closed voting, the Butler may raise their hand to vote but their vote is only counted if their master voted too."
			expect(ownJinxRules(base.game, 'butler', 'organgrinder', base.characters)).toEqual({
				voter: { countsOnlyWith: true }
			});
		});

		it("lets the Butler raise their hand without their master, and says it isn't counted", () => {
			// Wiki: "the Butler may raise their hand to vote but their vote is only counted if their master voted too."
			expect(uncountedVote(base.game, 'butler', base.characters)).toBe('organgrinder');
			expect(hint(base)).toEqual({
				characterId: 'butler',
				seats: [base.seat('monk')],
				uncounted: 'organgrinder'
			});
			expect(voteWarnings(base, 'butler')).toEqual([]);
		});

		it('keeps the usual rule while the Organ Grinder is drunk and voting is open', () => {
			// Wiki: "If the Organ Grinder is causing eyes closed voting"
			const s = base.reminder('organgrinder', 'organgrinder', 'Drunk');
			expect(uncountedVote(s.game, 'butler', s.characters)).toBeUndefined();
			expect(hint(s)?.uncounted).toBeUndefined();
			expect(voteWarnings(s, 'butler')).toEqual(['only-votes-with']);
		});
	});
});
